using PresenterConsole.Contracts; using PresenterConsole.Sync; namespace PresenterConsole.Sync.Tests; public sealed class SyncEngineTests { [Fact] public void DuplicateIdIgnored(){using var e=new SyncEngine();var n=0;e.CommandAccepted+=(_,_)=>n++;var c=new AgentCommand("x",1,CommandType.Next);Assert.True(e.TryAccept(c));Assert.False(e.TryAccept(c));Assert.Equal(1,n);} [Fact] public void OlderSequenceIgnored(){using var e=new SyncEngine();Assert.True(e.TryAccept(new("a",2,CommandType.Next)));Assert.False(e.TryAccept(new("b",1,CommandType.Next)));} }